"""The socket side: turns HTTP into a Request, runs the matched endpoint and sends its Reply."""

import sys
import traceback
from http.cookies import SimpleCookie
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import parse_qsl, unquote, urlsplit

from .auth import KeyGuard, is_home_network
from .chunked import ChunkedReader
from .errors import HarborError
from .messages import Reply, Request, error_reply, parse_range
from .router import Router

COPY_CHUNK = 1 << 20
BASE_HEADERS = (("X-Content-Type-Options", "nosniff"), ("Referrer-Policy", "no-referrer"))
HTML_POLICY = ("default-src 'self'; img-src 'self' blob: data:; media-src 'self'; "
               "style-src 'self'; script-src 'self'; frame-ancestors 'none'")


def _refusal(status: int, message: str, why: str, fix: str) -> Reply:
    return error_reply(HarborError(message, why, fix, status=status))


class HarborHandler(BaseHTTPRequestHandler):
    """Built per connection by ThreadingHTTPServer; ``router`` and ``guard`` come from the server."""

    protocol_version = "HTTP/1.1"
    server_version = "photo-harbor"

    def do_GET(self) -> None:
        self._dispatch("GET")

    def do_POST(self) -> None:
        self._dispatch("POST")

    def log_request(self, code="-", size="-") -> None:
        if self.command != "GET" or str(code)[:1] in ("4", "5"):
            super().log_request(code, size)

    def _dispatch(self, method: str) -> None:
        url = urlsplit(self.path)
        path = unquote(url.path)
        if not is_home_network(self.client_address[0]):
            self._send(_refusal(403, "only devices on the home network may connect",
                                f"{self.client_address[0]} is not a private address",
                                "connect the phone to the same Wi-Fi as the PC"))
            return
        route = self.server.router.match(method, path)
        if route is None:
            self._send(_refusal(404, f"nothing at {path}", "the address is not one photo-harbor serves",
                                "open the gallery at /"))
            return
        try:
            request = self._request(method, path, url.query)
            if not route.public and not self.server.guard.admits(request):
                raise HarborError("the library key is missing or wrong",
                                  "every call except the gallery page needs the key",
                                  "send the X-Harbor-Key header, or sign in on the gallery",
                                  status=401)
            reply = route.handler(request, route.param) if route.param else route.handler(request)
        except HarborError as error:
            reply = error_reply(error)
        except Exception:  # hygiene: allow last-resort guard so one bad request never stops the server
            traceback.print_exc(file=sys.stderr)
            reply = _refusal(500, "the server hit an unexpected problem",
                             "details are in the server window", "try again; report it if it repeats")
        self._send(reply)

    def _request(self, method: str, path: str, query: str) -> Request:
        headers = {key.lower(): value for key, value in self.headers.items()}
        cookies = {name: morsel.value for name, morsel in SimpleCookie(headers.get("cookie", "")).items()}
        body, length = self.rfile, None
        if "chunked" in headers.get("transfer-encoding", "").lower():
            body = ChunkedReader(self.rfile)
        else:
            try:
                length = int(headers.get("content-length", "0"))
            except ValueError as exc:
                raise HarborError("the Content-Length header is not a number", str(exc),
                                  "send a numeric Content-Length") from exc
            if length < 0:
                raise HarborError("the Content-Length header is negative", str(length),
                                  "send a non-negative Content-Length")
        return Request(method, path, dict(parse_qsl(query)), headers, cookies, body,
                       length if length is not None else 0) if length is not None or method == "GET" \
            else Request(method, path, dict(parse_qsl(query)), headers, cookies, body, -1)

    def _send(self, reply: Reply) -> None:
        if reply.status >= 400 and self.command == "POST":
            self.close_connection = True
        if reply.file is not None:
            self._send_file(reply)
            return
        self.send_response(reply.status)
        self._headers(reply, len(reply.body))
        self.end_headers()
        if self.command != "HEAD":
            self.wfile.write(reply.body)

    def _send_file(self, reply: Reply) -> None:
        size = reply.file.stat().st_size
        span = parse_range(self.headers.get("Range"), size)
        first, last = span if span else (0, size - 1)
        self.send_response(206 if span else 200)
        self._headers(reply, last - first + 1)
        self.send_header("Accept-Ranges", "bytes")
        if span:
            self.send_header("Content-Range", f"bytes {first}-{last}/{size}")
        self.end_headers()
        with open(reply.file, "rb") as handle:
            handle.seek(first)
            remaining = last - first + 1
            while remaining > 0:
                block = handle.read(min(COPY_CHUNK, remaining))
                if not block:
                    break
                self.wfile.write(block)
                remaining -= len(block)

    def _headers(self, reply: Reply, length: int) -> None:
        self.send_header("Content-Type", reply.content_type)
        self.send_header("Content-Length", str(length))
        for name, value in BASE_HEADERS + reply.headers:
            self.send_header(name, value)
        if reply.content_type.startswith("text/html"):
            self.send_header("Content-Security-Policy", HTML_POLICY)
        if self.close_connection:
            self.send_header("Connection", "close")


class HarborServer(ThreadingHTTPServer):
    daemon_threads = True

    def __init__(self, address: tuple, router: Router, guard: KeyGuard) -> None:
        self.router = router
        self.guard = guard
        super().__init__(address, HarborHandler)

"""Transport-free request and reply values, so the API can be tested without sockets."""

import json
from dataclasses import dataclass, field
from pathlib import Path
from typing import BinaryIO, Optional

from .errors import HarborError

MAX_JSON_BYTES = 64 * 1024


@dataclass(frozen=True)
class Request:
    method: str
    path: str
    query: dict = field(default_factory=dict)
    headers: dict = field(default_factory=dict)
    cookies: dict = field(default_factory=dict)
    body: Optional[BinaryIO] = None
    length: int = 0

    def header(self, name: str, default: str = "") -> str:
        return self.headers.get(name.lower(), default)

    def arg(self, name: str, default: str = "") -> str:
        return self.query.get(name, default)

    def json(self) -> dict:
        """The body as a JSON object, or HarborError for anything else."""
        if self.length > MAX_JSON_BYTES or self.body is None:
            raise HarborError("the request body was refused",
                              f"a JSON body must be 1 to {MAX_JSON_BYTES} bytes",
                              "send a small JSON object as the request body", status=413)
        try:
            data = json.loads(self.body.read(self.length).decode("utf-8") or "{}")
        except (UnicodeDecodeError, json.JSONDecodeError):
            data = None
        if not isinstance(data, dict):
            raise HarborError("the request body is not a JSON object",
                              "the server could not read it as {\"name\": value} pairs",
                              "set the Shortcut's Request Body to JSON")
        return data


@dataclass(frozen=True)
class Reply:
    status: int
    body: bytes = b""
    content_type: str = "application/json; charset=utf-8"
    headers: tuple = ()
    file: Optional[Path] = None


def json_reply(data, status: int = 200, headers: tuple = ()) -> Reply:
    return Reply(status, json.dumps(data, ensure_ascii=False).encode("utf-8"), headers=headers)


def error_reply(error: HarborError) -> Reply:
    return json_reply(error.as_dict(), status=error.status)


def parse_range(value: Optional[str], size: int) -> Optional[tuple]:
    """``(first, last)`` for one satisfiable ``bytes=`` range, else None for the whole file."""
    if not value or not value.startswith("bytes=") or "," in value or size == 0:
        return None
    first_text, _, last_text = value[6:].strip().partition("-")
    try:
        if first_text == "":
            first, last = max(size - int(last_text), 0), size - 1
        else:
            first = int(first_text)
            last = min(int(last_text), size - 1) if last_text else size - 1
    except ValueError:
        return None
    if first < 0 or first > last:
        return None
    return first, last

