:root {
  --bg: #f6f4f0;
  --surface: #ffffff;
  --surface-2: #ece8e1;
  --ink: #1d1f22;
  --muted: #6b6a66;
  --line: #ddd8cf;
  --accent: #1f6f6b;
  --accent-ink: #ffffff;
  --danger: #a33a2c;
  --tile: #e3ded5;
  --shadow: 0 1px 2px rgba(29, 31, 34, .06), 0 8px 24px rgba(29, 31, 34, .06);
  --radius: 14px;
  --gap: 3px;
  --sans: -apple-system, BlinkMacSystemFont, "Segoe UI Variable Text", "Segoe UI", system-ui, sans-serif;
  --serif: "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif;
  --mono: ui-monospace, "SF Mono", "Cascadia Mono", Consolas, monospace;
  color-scheme: light dark;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #121416;
    --surface: #1b1e21;
    --surface-2: #24282c;
    --ink: #ebe8e2;
    --muted: #9a978f;
    --line: #2e3337;
    --accent: #6cc3bb;
    --accent-ink: #0d1f1d;
    --danger: #ef8a7a;
    --tile: #23272b;
    --shadow: 0 1px 2px rgba(0, 0, 0, .3), 0 8px 24px rgba(0, 0, 0, .25);
  }
}

* { box-sizing: border-box; }
[hidden] { display: none !important; }

html, body { margin: 0; }
body {
  background: var(--bg);
  color: var(--ink);
  font: 15px/1.5 var(--sans);
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;
}

button, input { font: inherit; color: inherit; }
button { cursor: pointer; }
code { font-family: var(--mono); font-size: .88em; }

.mark { width: 28px; height: 28px; fill: none; stroke: var(--accent); stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }

.primary {
  background: var(--accent); color: var(--accent-ink);
  border: 0; border-radius: 999px; padding: 10px 20px; font-weight: 600;
}
.primary:hover { filter: brightness(1.06); }
.ghost {
  background: transparent; border: 1px solid var(--line); border-radius: 999px;
  padding: 5px 12px; font-size: 13px; color: var(--ink); text-decoration: none;
}
.ghost:hover { background: var(--surface-2); }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

/* Sign-in */
.login { min-height: 100dvh; display: grid; place-items: center; padding: 24px 16px; }
.login-card {
  width: min(380px, 100%); background: var(--surface); border-radius: 22px;
  padding: 36px 28px 28px; box-shadow: var(--shadow); text-align: center;
  display: grid; gap: 14px; justify-items: center;
}
.login-card .mark { width: 44px; height: 44px; }
.login-card h1 { font: 600 30px/1.1 var(--serif); margin: 0; letter-spacing: -.01em; }
.login-card p { margin: 0; color: var(--muted); }
.login-card input {
  width: 100%; padding: 12px 14px; border-radius: 12px; border: 1px solid var(--line);
  background: var(--bg); font-family: var(--mono); text-align: center;
}
.login-card .primary { width: 100%; padding: 12px; }
.login-error { color: var(--danger) !important; min-height: 1.5em; font-size: 14px; }

/* Shell */
.topbar {
  position: sticky; top: 0; z-index: 10;
  display: flex; align-items: center; gap: 20px; flex-wrap: wrap;
  padding: calc(env(safe-area-inset-top) + 12px) 20px 12px;
  background: color-mix(in srgb, var(--bg) 82%, transparent);
  backdrop-filter: saturate(1.6) blur(18px); -webkit-backdrop-filter: saturate(1.6) blur(18px);
  border-bottom: 1px solid color-mix(in srgb, var(--line) 70%, transparent);
}
.brand { display: flex; align-items: center; gap: 8px; font: 600 21px/1 var(--serif); }
.tabs { display: flex; gap: 2px; background: var(--surface-2); padding: 3px; border-radius: 999px; }
.tabs button {
  border: 0; background: transparent; padding: 6px 16px; border-radius: 999px;
  font-size: 14px; font-weight: 500; color: var(--muted);
}
.tabs button[aria-selected="true"] { background: var(--surface); color: var(--ink); box-shadow: var(--shadow); }
.summary { margin: 0 0 0 auto; color: var(--muted); font-size: 13px; font-variant-numeric: tabular-nums; }

main { padding: 8px 20px calc(env(safe-area-inset-bottom) + 40px); max-width: 1600px; margin: 0 auto; }

/* Photo days */
