  backdrop-filter: blur(6px); -webkit-backdrop-filter: blur(6px);
}
.tile .badge svg { width: 11px; height: 11px; fill: #fff; margin-left: 2px; }

.empty { text-align: center; padding: 18vh 16px; display: grid; gap: 10px; justify-items: center; }
.empty h2 { font: 600 28px/1.2 var(--serif); margin: 0; }
.empty p { color: var(--muted); max-width: 420px; margin: 0 0 8px; }
.sentinel { height: 1px; }

/* Sync and setup */
.cards { display: grid; gap: 14px; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); margin-top: 18px; }
.card, .panel { background: var(--surface); border-radius: var(--radius); padding: 18px 20px; box-shadow: var(--shadow); }
.card h3 { margin: 0 0 6px; font-size: 13px; font-weight: 500; color: var(--muted); }
.figure { margin: 0; font: 600 30px/1.15 var(--serif); font-variant-numeric: tabular-nums; }
.figure.small { font: 500 15px/1.6 var(--sans); }
.panel { margin-top: 16px; max-width: 860px; }
.panel h2 { font: 600 20px/1.3 var(--serif); margin: 0 0 8px; }
.hint { color: var(--muted); font-size: 14px; margin: 6px 0; }
.missing { list-style: none; margin: 10px 0 0; padding: 0; }
.missing li { display: flex; justify-content: space-between; gap: 12px; padding: 9px 0; border-top: 1px solid var(--line); font-size: 14px; }
.missing li:first-child { border-top: 0; }
.missing .none { color: var(--accent); }
.field { display: flex; align-items: center; gap: 12px; padding: 10px 0; border-top: 1px solid var(--line); }
.field:first-of-type { border-top: 0; }
.field span { width: 64px; color: var(--muted); font-size: 14px; }
.field code { flex: 1; word-break: break-all; background: var(--surface-2); padding: 6px 10px; border-radius: 8px; }
.steps ol, .steps ul { padding-left: 22px; margin: 8px 0; }
.steps li { margin: 8px 0; }
.steps li ol { margin-top: 6px; }
.steps code { background: var(--surface-2); padding: 1px 6px; border-radius: 6px; word-break: break-all; }

/* Viewer */
.viewer {
  position: fixed; inset: 0; z-index: 50; background: rgba(8, 9, 10, .96);
  display: grid; grid-template-rows: 1fr auto; color: #f2efe9;
  animation: fade .18s ease;
}
.viewer-stage { margin: 0; display: grid; place-items: center; min-height: 0; padding: 52px 64px 8px; }
.viewer-stage img, .viewer-stage video { max-width: 100%; max-height: 100%; object-fit: contain; border-radius: 4px; }
.viewer-stage .fallback { color: #aaa; text-align: center; }
.viewer-meta {
  display: flex; gap: 16px; align-items: center; flex-wrap: wrap; justify-content: center;
  padding: 12px 16px calc(env(safe-area-inset-bottom) + 14px); font-size: 14px;
}
.viewer-meta #viewer-detail { color: #a9a59d; }
.viewer-meta .ghost { color: #f2efe9; border-color: #444; }
.viewer-close, .viewer-nav {
  position: absolute; border: 0; background: rgba(255, 255, 255, .08); color: #f2efe9;
  border-radius: 50%; width: 42px; height: 42px; font-size: 22px; line-height: 1;
}
.viewer-close:hover, .viewer-nav:hover { background: rgba(255, 255, 255, .16); }
.viewer-close { top: calc(env(safe-area-inset-top) + 10px); right: 12px; font-size: 16px; }
.viewer-nav { top: 50%; transform: translateY(-50%); font-size: 30px; }
.viewer-nav.prev { left: 12px; }
.viewer-nav.next { right: 12px; }

.toast {
  position: fixed; left: 50%; bottom: calc(env(safe-area-inset-bottom) + 24px); transform: translateX(-50%);
  background: var(--ink); color: var(--bg); padding: 9px 18px; border-radius: 999px; font-size: 14px;
  box-shadow: var(--shadow); z-index: 60; animation: fade .2s ease;
}

@keyframes fade { from { opacity: 0; } to { opacity: 1; } }

@media (max-width: 640px) {
  :root { --gap: 2px; }
  .topbar { gap: 10px 14px; padding-left: 16px; padding-right: 16px; }
  .summary { width: 100%; margin: 0; order: 3; }
  main { padding-left: 0; padding-right: 0; }
  .day-head { padding-left: 16px; padding-right: 16px; top: 98px; }
  .grid { grid-template-columns: repeat(4, 1fr); border-radius: 0; }
  .cards, .panel, .empty { margin-left: 16px; margin-right: 16px; }
  .viewer-stage { padding: 56px 0 8px; }
  .viewer-nav { display: none; }
}
@media (max-width: 380px) { .grid { grid-template-columns: repeat(3, 1fr); } }
@media (prefers-reduced-motion: reduce) { * { animation: none !important; transition: none !important; } }

