  const count = el("span");
  head.append(el("h2", "", dayLabel(date)), count);
  const grid = el("div", "grid");
  section.append(head, grid);
  $("days").append(section);
  const group = { grid, count, n: 0 };
  state.dayEls.set(key, group);
  return group;
}

