"use strict";

const PAGE = 120;
const $ = (id) => document.getElementById(id);
const state = { photos: [], next: 0, loading: false, viewing: -1, dayEls: new Map() };

// ---------- server calls ----------

class Unauthorised extends Error {}

async function api(path, options = {}) {
  const response = await fetch(path, { credentials: "same-origin", ...options });
function el(tag, className, text) {
  const node = document.createElement(tag);
  if (className) node.className = className;
  if (text !== undefined) node.textContent = text;
  return node;
}

function toast(message) {
  const box = $("toast");
  box.textContent = message;
  box.hidden = false;
  clearTimeout(toast.timer);
  toast.timer = setTimeout(() => { box.hidden = true; }, 2200);
}

// ---------- tiles ----------
    group.count.textContent = group.n === 1 ? "1 item" : `${group.n} items`;
  }
}

async function loadMore() {
  if (state.loading || state.next === null) return;
  state.loading = true;
  try {
    const page = await api(`/api/photos?offset=${state.next}&limit=${PAGE}`);
    addPhotos(page.photos);
    state.next = page.next;
    $("empty").hidden = state.photos.length > 0;
  } catch (error) {
    handle(error);
  } finally {
    state.loading = false;
  }
}

function resetPhotos() {
  state.photos = [];
  state.next = 0;
  state.dayEls.clear();
  $("days").replaceChildren();
  return loadMore();
}

// ---------- viewer ----------

function openViewer(index) {
  const photo = state.photos[index];
  if (!photo) return;
  state.viewing = index;
  const stage = $("viewer-stage");
  stage.replaceChildren();
  if (photo.video) {
  const bar = document.querySelector(".topbar");
  new ResizeObserver(() => {
    document.documentElement.style.setProperty("--topbar-h", `${bar.offsetHeight}px`);
  }).observe(bar);
  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "visible" && !$("shell").hidden) refreshStatus().catch(handle);
  });
}

// ---------- sign-in ----------

function handle(error) {
  if (error instanceof Unauthorised) {
    $("shell").hidden = true;
    $("login").hidden = false;
    $("login-key").focus();
    return;
  }
  toast(error.message || "Something went wrong");
}

async function start() {
  try {
    await refreshStatus();
  } catch (error) {
    handle(error);
    return;
  }
  $("login").hidden = true;
  $("shell").hidden = false;
  let view = "photos";
  try { view = localStorage.getItem("harbor-view") || "photos"; } catch (_) { /* private mode */ }
  show(view);
  resetPhotos();
}

$("login-form").addEventListener("submit", async (event) => {
  event.preventDefault();
  $("login-error").textContent = "";
  try {
    await api("/api/login", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ key: $("login-key").value.trim() }),
    });
    start();

