"""Listing people and, for the library owner, adding, renaming and re-keying them."""

from .catalog import Catalog
from .errors import HarborError
from .journal import SyncJournal
from .messages import Reply, Request, json_reply
from .profiles import ProfileBook


def _require_owner(request: Request) -> None:
    if request.identity is None or not request.identity.owner:
        raise HarborError("only the main profile can manage profiles",
                          "this browser is signed in with another person's key",
                          "sign in with the library key shown in the Harbor window", status=403)


class ProfilesApi:
    def __init__(self, book: ProfileBook, catalog: Catalog, journal: SyncJournal) -> None:
        self._book = book
        self._catalog = catalog
        self._journal = journal

    def listing(self, request: Request) -> Reply:
        """Everyone with photo counts; keys only for the owner, or a person's own key."""
        me = request.identity
        people = []
        for profile in self._book.all():
            stats = self._catalog.stats(profile.id)
            entry = {"id": profile.id, "name": profile.name, "count": stats.count,
                     "bytes": stats.total_bytes, "last_sync": self._journal.last_sync(profile.id)}
            if me is not None and (me.owner or me.profile == profile.id):
                entry["key"] = profile.key
            people.append(entry)
        return json_reply({"me": me.profile if me else None, "owner": bool(me and me.owner),
                           "profiles": people})

    def create(self, request: Request) -> Reply:
        _require_owner(request)
        profile = self._book.create(str(request.json().get("name", "")))
        return json_reply({"id": profile.id, "name": profile.name, "key": profile.key})

    def update(self, request: Request, ident: str) -> Reply:
        """JSON ``{"name": "..."}`` renames; ``{"new_key": true}`` replaces the key."""
        _require_owner(request)
        body = request.json()
        name = body.get("name")
        profile = self._book.update(ident, name=str(name) if name is not None else None,
                                    new_key=body.get("new_key") is True)
        return json_reply({"id": profile.id, "name": profile.name, "key": profile.key})

