"""Listing people and, for the library owner, adding, renaming and re-keying them."""

from .catalog import Catalog
from .errors import HarborError
from .journal import SyncJournal
from .messages import Reply, Request, json_reply
from .profiles import ProfileBook


def _require_owner(request: Request) -> None:
    if request.identity is None or not request.identity.owner:
        raise HarborError("only the main profile can manage profiles",
                          "this browser is signed in with another person's key",
                          "sign in with the library key shown in the Harbor window", status=403)


class ProfilesApi:
    def __init__(self, book: ProfileBook, catalog: Catalog, journal: SyncJournal) -> None:
        self._book = book
        self._catalog = catalog
        self._journal = journal

    def listing(self, request: Request) -> Reply:
        """Everyone with photo counts; keys only for the owner, or a person's own key."""
        me = request.identity
        people = []
        for profile in self._book.all():
            stats = self._catalog.stats(profile.id)
            entry = {"id": profile.id, "name": profile.name, "count": stats.count,
                     "bytes": stats.total_bytes, "last_sync": self._journal.last_sync(profile.id)}
            if me is not None and (me.owner or me.profile == profile.id):
                entry["key"] = profile.key
            people.append(entry)
        return json_reply({"me": me.profile if me else None, "owner": bool(me and me.owner),
                           "profiles": people})

    def create(self, request: Request) -> Reply:
        _require_owner(request)
        profile = self._book.create(str(request.json().get("name", "")))
        return json_reply({"id": profile.id, "name": profile.name, "key": profile.key})

    def update(self, request: Request, ident: str) -> Reply:
        """JSON ``{"name": "..."}`` renames; ``{"new_key": true}`` replaces the key."""
        _require_owner(request)
        body = request.json()
        name = body.get("name")
        profile = self._book.update(ident, name=str(name) if name is not None else None,
                                    new_key=body.get("new_key") is True)
        return json_reply({"id": profile.id, "name": profile.name, "key": profile.key})

"""Bringing photos already on the PC's disk into a profile, without touching the source folder."""

import os
import threading
from dataclasses import dataclass
from datetime import datetime, timezone
from pathlib import Path
from typing import Callable, Optional

from .errors import HarborError
from .records import UploadClaim
from .store import PhotoStore

MEDIA_SUFFIXES = frozenset({
    ".jpg", ".jpeg", ".png", ".gif", ".webp", ".heic", ".heif", ".tif", ".tiff", ".dng", ".bmp",
    ".mov", ".mp4", ".m4v", ".avi", ".3gp", ".mkv",
})


@dataclass(frozen=True)
class ImportReport:
    stored: int
    duplicate: int
    failed: int
    errors: tuple

    @property
    def summary(self) -> str:
        return (f"{self.stored} added, {self.duplicate} already in Harbor, "
                f"{self.failed} could not be read")


def find_media(folder: Path, library: Path) -> list:
    """Photos and videos under ``folder``, sorted; the Harbor library itself is skipped."""
    source, own = folder.resolve(), library.resolve()
    if source == own or own in source.parents:
        raise HarborError(f"{folder} is inside the Harbor library",
                          "importing the library into itself would copy nothing new",
                          "choose a folder outside it, such as an old phone backup")
    found = []
    for root, dirs, files in os.walk(source):
        here = Path(root)
        dirs[:] = sorted(d for d in dirs if (here / d).resolve() != own and not d.startswith("."))
        found.extend(here / name for name in sorted(files)
                     if Path(name).suffix.lower() in MEDIA_SUFFIXES)
    return found


def _modified(path: Path) -> str:
    return datetime.fromtimestamp(path.stat().st_mtime, timezone.utc).isoformat(timespec="seconds")


def import_folder(store: PhotoStore, folder: Path, library: Path, profile: str,
                  progress: Optional[Callable[[int, int, Path], None]] = None,
                  stop: Optional[threading.Event] = None) -> ImportReport:
    """Copy each photo in; each file is hashed by the store, so re-running adds only new ones."""
    files = find_media(folder, library)
    stored = duplicate = failed = 0
    errors = []
    for index, path in enumerate(files):
        if stop is not None and stop.is_set():
            break
        if progress is not None:
            progress(index, len(files), path)
        claim = UploadClaim(original_name=path.name, modified_at=None, profile=profile)
        try:
            claim = UploadClaim(original_name=path.name, modified_at=_modified(path), profile=profile)
            with open(path, "rb") as handle:
                result = store.ingest(handle, path.stat().st_size, claim)
        except (OSError, HarborError) as error:
            failed += 1
            errors.append(f"{path}: {getattr(error, 'message', error)}")
            continue
        if result.status == "stored":
            stored += 1
        else:
            duplicate += 1
    if progress is not None:
        progress(len(files), len(files), folder)
    return ImportReport(stored, duplicate, failed, tuple(errors[:50]))

